# ─── Markdown 解析 ──────────────────────────────────────────────────────────

def parse_md_to_blocks(md_text):
    """将Markdown解析为渲染块列表。"""
    blocks = []
    # 去掉 <style>...</style> 和 HTML 标签
    md_text = re.sub(r'<style>.*?</style>', '', md_text, flags=re.DOTALL)
    md_text = re.sub(r'<[^>]+>', '', md_text)

    lines = md_text.split('\n')
    i = 0
    while i < len(lines):
        line = lines[i].rstrip()

        # 跳过空行
        if not line:
            blocks.append({"type": "spacer", "height": int(FONT_SIZE_BODY * 0.8)})
            i += 1
            continue

        # 标题
        if line.startswith('## '):
            blocks.append({"type": "h2", "text": line[3:].strip()})
            i += 1
            continue
        if line.startswith('# '):
            blocks.append({"type": "h2", "text": line[2:].strip()})
            i += 1
            continue

        # 分隔线
        if re.match(r'^-{3,}$', line) or re.match(r'^\*{3,}$', line):
            blocks.append({"type": "separator"})
            i += 1
            continue

        # 普通段落（收集连续非空行）
        para_lines = []
        while i < len(lines) and lines[i].strip():
            para_lines.append(lines[i].strip())
            i += 1
        text = ' '.join(para_lines)
        blocks.append({"type": "paragraph", "text": text})
        continue

    return blocks


# ─── 渲染 ───────────────────────────────────────────────────────────────────

def wrap_text(text, font, max_width, draw):
    """手动按像素宽度换行，支持中文。"""
    lines = []
    current_line = ""
    for char in text:
        test = current_line + char
        bbox = draw.textbbox((0, 0), test, font=font)
        w = bbox[2] - bbox[0]
        if w > max_width and current_line:
            lines.append(current_line)
            current_line = char
        else:
            current_line = test
    if current_line:
        lines.append(current_line)
    return lines


def render_text_segment(text, font, color, draw, max_width):
    """返回渲染后的行列表和总高度。"""
    lines = wrap_text(text, font, max_width, draw)
    line_height = int(FONT_SIZE_BODY * LINE_SPACING)
    return lines, len(lines) * line_height


def estimate_block_height(block, fonts, draw):
    """估算一个块的渲染高度。"""
    if block["type"] == "spacer":
        return block["height"]
    if block["type"] == "separator":
        return int(FONT_SIZE_BODY * 2)
    if block["type"] == "h2":
        lines = wrap_text(block["text"], fonts["h2"], CONTENT_WIDTH, draw)
        return len(lines) * int(FONT_SIZE_H2 * LINE_SPACING) + 20
    if block["type"] == "paragraph":
        # 简化：用body字体估算
        clean = re.sub(r'\*\*([^*]+)\*\*', r'\1', block["text"])
        lines = wrap_text(clean, fonts["body"], CONTENT_WIDTH, draw)
        return len(lines) * int(FONT_SIZE_BODY * LINE_SPACING)
    return 0


def draw_block(block, fonts, draw, x, y):
    """在指定位置绘制块，返回消耗的高度。"""
    if block["type"] == "spacer":
        return block["height"]

    if block["type"] == "separator":
        sep_y = y + FONT_SIZE_BODY
        draw.line([(x, sep_y), (x + CONTENT_WIDTH, sep_y)], fill=SEPARATOR_COLOR, width=2)
        return int(FONT_SIZE_BODY * 2)

    if block["type"] == "h2":
        lines = wrap_text(block["text"], fonts["h2"], CONTENT_WIDTH, draw)
        line_h = int(FONT_SIZE_H2 * LINE_SPACING)
        for i, line in enumerate(lines):
            draw.text((x, y + i * line_h), line, font=fonts["h2"], fill=HEADING_COLOR)
        return len(lines) * line_h + 20

    if block["type"] == "paragraph":
        # 简单处理加粗：去掉**标记，整段用同一字体渲染
        # （完整的 inline bold 渲染过于复杂，这里简化处理）
        clean = re.sub(r'\*\*([^*]+)\*\*', r'\1', block["text"])
        lines = wrap_text(clean, fonts["body"], CONTENT_WIDTH, draw)
        line_h = int(FONT_SIZE_BODY * LINE_SPACING)
        for i, line in enumerate(lines):
            draw.text((x, y + i * line_h), line, font=fonts["body"], fill=TEXT_COLOR)
        return len(lines) * line_h

    return 0


